oxy_webhelp_navlinks = {"tocId-d39536e2055":{"topics":[{"title":"Key features of System Tags","shortdesc":"<p class=\"shortdesc\">System Tags in <span class=\"ph\">RSC<\/span> provide flexible and efficient methods for         managing data protection through enhanced object visibility and reporting.<\/p>","href":"system_tags\/key_features_system_tags.html","attributes":{"data-id":"key_features_system_tags"},"menu":{"hasChildren":false},"tocID":"key_features_system_tags-d39536e2056","topics":[]},{"title":"System Tag keys and values","shortdesc":"<p class=\"shortdesc\">System Tags support an optional key paired with a required value, enabling you to         more precisely categorize and filter data assets in <span class=\"ph\">RSC<\/span>.<\/p>","href":"system_tags\/system_tag_keys_and_values.html","attributes":{"data-id":"system_tag_keys_and_values"},"menu":{"hasChildren":false},"tocID":"system_tag_keys_and_values-d39536e2070","topics":[]},{"title":"System Tag assignment for SCVMM native tags","shortdesc":"<p class=\"shortdesc\">You can assign <span class=\"ph\">RSC<\/span> System Tags to System Center Virtual Machine         Manager native tags from your System Center Virtual Machine Manager environment to automate         SLA Domain assignment for Hyper-V virtual machines.<\/p>","href":"system_tags\/native_tags_scvmm.html","attributes":{"data-id":"native_tags_scvmm"},"menu":{"hasChildren":false},"tocID":"native_tags_scvmm-d39536e2084","topics":[]}]}};